-- Esquema base de ChloeRest POS -- Tablas esenciales que runMigrations() espera (las migraciones solo alteran/agregan). -- Aplicar solo en instalaciones nuevas (BD vacía).  CREATE TABLE IF NOT EXISTS usuarios (   id SERIAL PRIMARY KEY,   nombre VARCHAR(200) NOT NULL,   rol VARCHAR(50) NOT NULL DEFAULT 'Cajero',   pin VARCHAR(10),   pin_hash TEXT,   estado VARCHAR(20) NOT NULL DEFAULT 'Activo',   creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP );  CREATE TABLE IF NOT EXISTS productos (   id SERIAL PRIMARY KEY,   nombre VARCHAR(200) NOT NULL,   descripcion TEXT,   precio NUMERIC(10,2) NOT NULL DEFAULT 0,   imagen_url TEXT,   categoria VARCHAR(50) DEFAULT 'Cocina',   estado VARCHAR(20) NOT NULL DEFAULT 'Activo' );  CREATE TABLE IF NOT EXISTS ingredientes (   id SERIAL PRIMARY KEY,   numero_articulo VARCHAR(50),   nombre VARCHAR(200) NOT NULL,   categoria VARCHAR(100),   stock_actual NUMERIC(10,4) NOT NULL DEFAULT 0,   unidad_medida VARCHAR(30) DEFAULT 'Unidad' );  CREATE TABLE IF NOT EXISTS clientes_frecuentes (   id SERIAL PRIMARY KEY,   nombre VARCHAR(200) NOT NULL,   telefono VARCHAR(30),   direccion TEXT );  CREATE TABLE IF NOT EXISTS mesas (   id SERIAL PRIMARY KEY,   nombre_numero VARCHAR(50) NOT NULL,   capacidad INTEGER NOT NULL DEFAULT 2,   estado VARCHAR(20) NOT NULL DEFAULT 'Disponible',   camarero_id INTEGER REFERENCES usuarios(id) );  CREATE TABLE IF NOT EXISTS cuentas (   id BIGSERIAL PRIMARY KEY,   mesa_id INTEGER REFERENCES mesas(id),   camarero_id INTEGER REFERENCES usuarios(id),   cliente_id INTEGER REFERENCES clientes_frecuentes(id),   cajero_id INTEGER REFERENCES usuarios(id),   estado VARCHAR(20) NOT NULL DEFAULT 'Abierta',   tipo_servicio VARCHAR(30) DEFAULT 'En Mesa',   tipo_comprobante VARCHAR(10),   ncf_ecf_generado VARCHAR(50),   rnc_cedula_cliente VARCHAR(20),   tarjeta_ultimos_4 VARCHAR(10),   tarjeta_marca VARCHAR(50),   metodo_pago VARCHAR(20),   metodo_pago_2 VARCHAR(20),   monto_pago_2 NUMERIC(10,2) DEFAULT 0,   banco_pago_2 VARCHAR(100),   moneda_pago VARCHAR(10) DEFAULT 'DOP',   monto_extranjero NUMERIC(10,2) DEFAULT 0,   tasa_cambio NUMERIC(10,4) DEFAULT 1,   subtotal NUMERIC(10,2) NOT NULL DEFAULT 0,   itbis NUMERIC(10,2) NOT NULL DEFAULT 0,   propina NUMERIC(10,2) NOT NULL DEFAULT 0,   total NUMERIC(10,2) NOT NULL DEFAULT 0,   fecha_apertura TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,   fecha_cierre TIMESTAMP );  CREATE TABLE IF NOT EXISTS cuenta_detalles (   id BIGSERIAL PRIMARY KEY,   cuenta_id INTEGER NOT NULL REFERENCES cuentas(id) ON DELETE CASCADE,   producto_id INTEGER NOT NULL REFERENCES productos(id),   cantidad NUMERIC(10,2) NOT NULL DEFAULT 1,   precio_unitario NUMERIC(10,2) NOT NULL DEFAULT 0,   estado_cocina VARCHAR(30) DEFAULT 'Pendiente',   hora_pedido TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,   anulado_en TIMESTAMP,   anulado_por INTEGER REFERENCES usuarios(id),   motivo_anulacion TEXT );  CREATE TABLE IF NOT EXISTS negocio_config (   id SERIAL PRIMARY KEY,   nombre_comercial VARCHAR(200) DEFAULT 'Mi Restaurante',   razon_social VARCHAR(200),   rnc VARCHAR(20) DEFAULT '130000001',   telefono VARCHAR(30),   direccion TEXT,   provincia VARCHAR(100),   regimen_fiscal VARCHAR(50),   nombre_cocina VARCHAR(100),   nombre_bar VARCHAR(100),   duracion_meses INTEGER DEFAULT -1,   logo_url TEXT,   estado_licencia VARCHAR(50) DEFAULT 'Activa',   cobrar_itbis BOOLEAN NOT NULL DEFAULT TRUE,   cobrar_propina BOOLEAN NOT NULL DEFAULT TRUE,   licencia_bloqueada BOOLEAN NOT NULL DEFAULT FALSE,   fecha_instalacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,   propietario VARCHAR(200),   email VARCHAR(200),   fecha_registro TIMESTAMP,   tasa_usd NUMERIC(10,4) DEFAULT 60.00,   tasa_eur NUMERIC(10,4) DEFAULT 65.00 );  CREATE TABLE IF NOT EXISTS menu_categorias (   id SERIAL PRIMARY KEY,   nombre VARCHAR(100) NOT NULL,   grupo VARCHAR(50) DEFAULT 'Cocina' );  CREATE TABLE IF NOT EXISTS menu_guarniciones (   id SERIAL PRIMARY KEY,   nombre VARCHAR(100) NOT NULL );  CREATE TABLE IF NOT EXISTS menu_terminos (   id SERIAL PRIMARY KEY,   nombre VARCHAR(100) NOT NULL );